@font-face { font-family: "Bangers"; src: url("fonts/bangers-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Archivo"; src: url("fonts/archivo-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Archivo"; src: url("fonts/archivo-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Archivo"; src: url("fonts/archivo-latin-800-normal.woff2") format("woff2"); font-weight: 800; font-display: swap; }

:root {
  --preto: #111;
  --branco: #fff;
  --vermelho: #E3120B;
  --amarelo: #FFD400;
  --ciano: #00B4E6;
  --magenta: #FF2D8A;
  --papel: #FFFBEF;
  --pontos: radial-gradient(circle, rgba(0, 0, 0, .14) 26%, transparent 28%);
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  font-family: "Archivo", system-ui, sans-serif;
  color: var(--preto);
  background: var(--vermelho);
  overflow: hidden;
}

.tela { display: none; position: fixed; inset: 0; }
.tela.ativa { display: flex; }

/* ---------- elementos comuns ---------- */

.botao {
  font-family: "Archivo", sans-serif;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: .3px;
  text-transform: uppercase;
  padding: 10px 16px;
  border: 3px solid var(--preto);
  background: var(--branco);
  color: var(--preto);
  box-shadow: 4px 4px 0 var(--preto);
  cursor: pointer;
  transition: transform .08s, box-shadow .08s, background .15s;
  white-space: nowrap;
}
.botao:hover:not(:disabled) { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--preto); }
.botao:active:not(:disabled) { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--preto); }
.botao:disabled { opacity: .35; cursor: not-allowed; box-shadow: none; }
.botao-vermelho { background: var(--vermelho); color: var(--branco); }
.botao-amarelo { background: var(--amarelo); }
.botao.ligado { background: var(--ciano); }
.botao.grande { font-family: "Bangers", sans-serif; font-weight: 400; font-size: 30px; letter-spacing: 2px; padding: 8px 28px; }
.botao.quadrado { width: 42px; padding: 6px 0; font-size: 22px; line-height: 1; }

.balao {
  position: relative;
  display: inline-block;
  font-family: "Bangers", sans-serif;
  font-size: 34px;
  letter-spacing: 2px;
  background: var(--amarelo);
  border: 4px solid var(--preto);
  border-radius: 50% / 44%;
  padding: 10px 28px;
}
.balao::after {
  content: "";
  position: absolute;
  left: 26%;
  bottom: -22px;
  border: 12px solid transparent;
  border-top: 18px solid var(--preto);
  border-left-width: 4px;
}

.campo {
  font: inherit;
  font-size: 22px;
  font-weight: 700;
  width: 100%;
  padding: 12px 14px;
  border: 4px solid var(--preto);
  background: var(--branco);
  box-shadow: 5px 5px 0 var(--preto);
  outline: none;
}
.campo:focus { background: #FFF6C2; }

/* ---------- 1. boas-vindas ---------- */

#tela-boasvindas { align-items: center; justify-content: center; background: var(--vermelho); }
.moldura { position: absolute; inset: 22px; border: 5px solid var(--preto); }

.penas { background: url("penas.jpg") center / cover no-repeat; }

.boasvindas-coluna { position: relative; display: flex; flex-direction: column; align-items: center; }
.logo-grande {
  position: relative;
  z-index: 2;
  width: min(540px, 92vw, calc((100vh - 380px) * 1.5));
  margin-bottom: -96px;
  filter: drop-shadow(6px 6px 0 rgba(17, 17, 17, .35));
}
.logo-grande svg, .logo-mini svg { display: block; width: 100%; height: auto; }

.cartao {
  position: relative;
  width: min(480px, 88vw);
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 104px 40px 32px;
  background: var(--branco);
  border: 5px solid var(--preto);
  box-shadow: 14px 14px 0 var(--vermelho), 14px 14px 0 5px var(--preto);
}
.titulo-boasvindas { margin: 0; font-family: "Bangers", sans-serif; font-weight: 400; font-size: 40px; letter-spacing: 2px; color: var(--vermelho); }
.rotulo { font-weight: 800; font-size: 15px; text-transform: uppercase; letter-spacing: .5px; }
.aviso { min-height: 20px; font-weight: 700; color: var(--vermelho); }
.linha-botoes { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.botao-ajuda { display: inline-flex; align-items: center; gap: 10px; padding: 6px 14px 6px 6px; }
.interrogacao {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  font-family: "Bangers", sans-serif;
  font-size: 24px;
  border: 3px solid var(--preto);
  border-radius: 50%;
  background: var(--amarelo);
}

/* ---------- 2. assinar ---------- */

#tela-assinar { flex-direction: column; background: var(--branco); }

.topo { display: flex; align-items: center; gap: 18px; padding: 6px 20px; background: var(--preto); }
.logo-mini { width: 250px; flex: none; margin: -6px 0; }
.dica {
  flex: 1;
  font-weight: 700;
  font-size: 15px;
  padding: 9px 16px;
  background: var(--branco);
  border: 3px solid var(--amarelo);
}

.ferramentas {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 12px 20px 14px;
  background: var(--amarelo) var(--pontos);
  background-size: 10px 10px;
  border-bottom: 4px solid var(--preto);
}
.zoom { display: flex; align-items: center; gap: 6px; }
#zoom-valor {
  min-width: 64px;
  text-align: center;
  font-weight: 800;
  padding: 8px 4px;
  background: var(--branco);
  border: 3px solid var(--preto);
}

.visor {
  position: relative;
  flex: 1;
  overflow: auto;
  background: #E8E8E8 var(--pontos);
  background-size: 14px 14px;
}
.visor.modo-area .pagina { cursor: crosshair; }

.vazio {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 40px;
}
.vazio.escondido { display: none; }

.paginas {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 30px;
  padding: 30px;
  min-width: max-content;
}
.pagina {
  position: relative;
  flex: none;
  background: var(--branco);
  outline: 3px solid var(--preto);
  box-shadow: 9px 9px 0 var(--preto);
  user-select: none;
  touch-action: pan-x pan-y;
}
.pagina canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }

.area {
  position: absolute;
  border: 3px dashed var(--vermelho);
  background: rgba(227, 18, 11, .10);
  pointer-events: none;
}
.area span {
  position: absolute;
  top: -26px;
  left: -3px;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
  color: var(--branco);
  background: var(--vermelho);
  padding: 3px 8px;
  white-space: nowrap;
}

.assinatura { position: absolute; cursor: move; outline: 2px dashed var(--ciano); touch-action: none; }
.assinatura img { display: block; width: 100%; height: 100%; mix-blend-mode: multiply; pointer-events: none; user-select: none; }
.puxador { position: absolute; width: 14px; height: 14px; background: var(--amarelo); border: 2px solid var(--preto); }
.puxador[data-d="nw"] { left: -8px; top: -8px; cursor: nwse-resize; }
.puxador[data-d="n"]  { left: calc(50% - 7px); top: -8px; cursor: ns-resize; }
.puxador[data-d="ne"] { right: -8px; top: -8px; cursor: nesw-resize; }
.puxador[data-d="e"]  { right: -8px; top: calc(50% - 7px); cursor: ew-resize; }
.puxador[data-d="se"] { right: -8px; bottom: -8px; cursor: nwse-resize; }
.puxador[data-d="s"]  { left: calc(50% - 7px); bottom: -8px; cursor: ns-resize; }
.puxador[data-d="sw"] { left: -8px; bottom: -8px; cursor: nesw-resize; }
.puxador[data-d="w"]  { left: -8px; top: calc(50% - 7px); cursor: ew-resize; }

/* janelinha de pergunta */
.modal-fundo {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(17, 17, 17, .55);
}
.modal-caixa {
  width: min(540px, 92vw);
  padding: 26px 28px 28px;
  background: var(--branco);
  border: 5px solid var(--preto);
  box-shadow: 12px 12px 0 var(--amarelo), 12px 12px 0 5px var(--preto);
}
.modal-caixa h3 { margin: 0 0 8px; font-family: "Bangers", sans-serif; font-weight: 400; font-size: 36px; letter-spacing: 1.5px; }
.modal-caixa p { margin: 0 0 18px; font-size: 17px; line-height: 1.4; }
.modal-caixa .campo { margin-bottom: 22px; font-size: 18px; }
.modal-caixa .passos { margin: 0 0 14px; padding-left: 22px; font-size: 16px; line-height: 1.4; }
.modal-caixa .passos li { margin-bottom: 6px; padding-left: 4px; }
.modal-caixa .passos li::marker { font-family: "Bangers", sans-serif; font-size: 20px; color: var(--vermelho); }
.modal-caixa .nota { font-size: 14px; font-weight: 700; background: var(--amarelo); border: 3px solid var(--preto); padding: 8px 12px; }
.modal-caixa.larga { width: min(600px, 94vw); max-height: 90vh; overflow: auto; }
.modal-botoes { display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end; }

/* ---------- 3. biscoito da sorte ---------- */

#tela-biscoito {
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  overflow: hidden;
  background: var(--vermelho);
}
#tela-biscoito::before {
  content: "";
  position: absolute;
  inset: 22px;
  border: 5px solid var(--preto);
  background: var(--branco) url("manchas.svg") center / cover no-repeat;
  pointer-events: none;
}

.parabens {
  position: relative;
  max-width: min(860px, 92vw);
  padding: 16px 30px 18px;
  text-align: center;
  background: var(--branco);
  border: 5px solid var(--preto);
  box-shadow: 10px 10px 0 var(--preto);
  transform: rotate(-1.5deg);
}
.parabens h1 { margin: 0; font-family: "Bangers", sans-serif; font-weight: 400; font-size: clamp(30px, 4.2vw, 50px); line-height: 1.05; letter-spacing: 1.5px; }
.parabens h2 { margin: 6px 0 0; font-family: "Bangers", sans-serif; font-weight: 400; font-size: clamp(26px, 3.4vw, 42px); letter-spacing: 1.5px; color: var(--vermelho); }

.palco { position: relative; width: min(820px, 96vw); height: min(420px, 52vh); }

.biscoito {
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(440px, 70vw);
  max-height: 100%;
  transform: translate(-50%, -50%);
  cursor: pointer;
  overflow: visible;
  filter: drop-shadow(8px 8px 0 rgba(17, 17, 17, .9));
}
.biscoito .metade { transform-box: fill-box; transition: transform .75s cubic-bezier(.3, 1.4, .5, 1), opacity .75s; }
.biscoito .metade.esq { transform-origin: 100% 100%; }
.biscoito .metade.dir { transform-origin: 0% 100%; }
.biscoito .explosao { transform-box: fill-box; transform-origin: center; animation: girar 18s linear infinite; }
.biscoito .migalha { transform-box: fill-box; transform-origin: center; fill: #E39A3B; stroke: var(--preto); stroke-width: 2; opacity: 0; }

.biscoito { transition: transform .15s; }
.palco:not(.quebrado) .biscoito:hover { transform: translate(-50%, -50%) scale(1.04); }
.palco.treme .biscoito { animation: tremer .45s ease-in-out; }
.palco.quebrado .metade.esq { transform: translate(-165px, 14px) rotate(-16deg); }
.palco.quebrado .metade.dir { transform: translate(165px, 14px) rotate(16deg); }
.palco.quebrado .migalha { animation: voar .9s ease-out forwards; }
.palco.quebrado .biscoito { cursor: default; }

.seta {
  position: absolute;
  left: 2%;
  top: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transform: translateY(-50%);
  animation: apontar 1s ease-in-out infinite;
  transition: opacity .3s;
  pointer-events: none;
}
.seta span {
  font-family: "Bangers", sans-serif;
  font-size: 30px;
  letter-spacing: 2px;
  padding: 4px 14px;
  background: var(--branco);
  border: 4px solid var(--preto);
  box-shadow: 5px 5px 0 var(--preto);
  transform: rotate(-6deg);
}
.seta svg { width: 120px; }
.palco.treme .seta, .palco.quebrado .seta { opacity: 0; }

.recomecar { position: relative; opacity: 0; visibility: hidden; transform: translateY(10px); transition: opacity .4s, transform .4s, visibility .4s; }
.recomecar.visivel { opacity: 1; visibility: visible; transform: none; }

/* papelzinho */
.papel {
  --pw: min(600px, 88vw);
  --ph: 150px;
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--pw);
  height: var(--ph);
  opacity: 0;
  pointer-events: none;
  perspective: 1400px;
  filter: drop-shadow(7px 7px 0 rgba(17, 17, 17, .9));
  transform: translate(-50%, -10%) scale(.35);
  transition: transform .7s cubic-bezier(.2, 1.5, .4, 1), opacity .25s;
}
.palco.papel-sai .papel { opacity: 1; transform: translate(-50%, -62%) scale(1); }

.dobras { display: flex; width: 100%; height: 100%; transform-style: preserve-3d; }
.seg { position: relative; width: calc(var(--pw) / 3); height: 100%; transform-style: preserve-3d; transition: transform .6s cubic-bezier(.4, 1.3, .6, 1); }
.seg-e { transform-origin: right center; transform: rotateY(180deg) translateZ(-1px); }
.seg-d { transform-origin: left center; transform: rotateY(-180deg) translateZ(-2px); }
.palco.desdobrado .seg-d { transform: rotateY(0deg); }
.palco.desdobrado .seg-e { transform: rotateY(0deg); transition-delay: .35s; }

.face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: var(--papel);
  border-top: 3px solid var(--preto);
  border-bottom: 3px solid var(--preto);
}
.seg-e .face { border-left: 3px solid var(--preto); }
.seg-d .face { border-right: 3px solid var(--preto); }
.seg-c .face { border-left: 1px dashed #c9c0a8; border-right: 1px dashed #c9c0a8; }
.verso { transform: rotateY(180deg); background: #F2EBD7; border: 3px solid var(--preto); }

.texto {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--pw);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 40px;
  text-align: center;
  font-weight: 800;
  font-size: clamp(17px, 2.2vw, 23px);
  line-height: 1.3;
  color: var(--preto);
}
.texto::before, .texto::after { content: "★"; color: var(--vermelho); font-size: 18px; margin: 0 12px; flex: none; }
.seg-c .texto { left: calc(var(--pw) / -3); }
.seg-d .texto { left: calc(var(--pw) * -2 / 3); }

@keyframes tremer {
  0%, 100% { transform: translate(-50%, -50%) rotate(0); }
  20% { transform: translate(-50%, -50%) rotate(-5deg); }
  40% { transform: translate(-50%, -50%) rotate(5deg); }
  60% { transform: translate(-50%, -50%) rotate(-4deg); }
  80% { transform: translate(-50%, -50%) rotate(3deg); }
}
@keyframes voar {
  0% { opacity: 1; transform: translate(0, 0) rotate(0); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) rotate(220deg); }
}
@keyframes apontar {
  0%, 100% { transform: translate(0, -50%); }
  50% { transform: translate(18px, -50%); }
}
@keyframes girar { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
  .biscoito .explosao, .seta { animation: none; }
}

